PROFILE Interchange

COMPONENT Scripting : 1

DEF NAV1 NavigationInfo {
  type "EXAMINE"
}

DEF NAV2 NavigationInfo {
  type "FLY"
  headlight FALSE
}

DEF VP1 Viewpoint {
  description "one"
  position 0 0 8
  navigationInfo USE NAV1
}

DEF VP2 Viewpoint {
  description "two"
  position 3 1 7
  orientation 0 1 0 0.4
  navigationInfo USE NAV2
}

DirectionalLight {
  intensity 0.3
  direction 0 -1 -1
}

Shape {
  appearance Appearance {
    material Material {
      diffuseColor 0.8 0.3 0.3
    }
  }
  geometry Box { }
}

DEF S Script {
  inputOnly   SFTime  tick
  inputOutput SFInt32 n 1
  outputOnly  SFBool  bind2

  url "ecmascript:
    function tick (v) {
      n = n + 1;
      if (n == 3) bind2 = true;
      if (n == 7) bind2 = false;
    }
  "
}

DEF T TimeSensor {
  cycleInterval 0.1
  loop TRUE
}

ROUTE T.cycleTime TO S.tick
ROUTE S.bind2 TO VP2.set_bind

